head.script:
scwin.onpageload = function() {
    //데이터리스트 동적생성.
    scwin.makeDataList();
    //동적생성 데이터리스트 데이터 셋팅.
    var jsonData_dl = [{
        "codeNm": "dl_라벨A-1",
        "codeNo": "A-1",
        "upper": "A"
    }, {
        "codeNm": "dl_라벨A-2",
        "codeNo": "A-2",
        "upper": "A"
    }, {
        "codeNm": "dl_라벨B-1",
        "codeNo": "B-1",
        "upper": "B"
    }, {
        "codeNm": "dl_라벨B-2",
        "codeNo": "B-2",
        "upper": "B"
    }, {
        "codeNm": "dl_라벨C-1",
        "codeNo": "C-1",
        "upper": "C"
    }, {
        "codeNm": "dl_라벨C-2",
        "codeNo": "C-2",
        "upper": "C"
    }, {
        "codeNm": "dl_라벨D-1",
        "codeNo": "D-1",
        "upper": "D"
    }, {
        "codeNm": "dl_라벨D-2",
        "codeNo": "D-2",
        "upper": "D"
    }];
    dl_dynamic.setJSON(jsonData_dl);
    //첫번째 selectbox 컬럼 아이템 셋팅 
    var jsonData1 = [{
        "label": "라벨A",
        "value": "A"
    }, {
        "label": "라벨B",
        "value": "B"
    }, {
        "label": "라벨C",
        "value": "C"
    }, {
        "label": "라벨D",
        "value": "D"
    }];
    dl_sel.setJSON(jsonData1);
    //그리드뷰 데이터 셋팅.
    var jsonData3 = [{
        "col1": "A",
        "col2": "A-1"
    }, {
        "col1": "B",
        "col2": "B-1"
    }, {
        "col1": "C",
        "col2": "C-1"
    }, {
        "col1": "C",
        "col2": "C-2"
    }, {
        "col1": "B",
        "col2": "B-2"
    }, {
        "col1": "B",
        "col2": "B-1"
    }, {
        "col1": "B",
        "col2": "B-2"
    }, {
        "col1": "A",
        "col2": "A-2"
    }];
    dl_grid.setJSON(jsonData3);
};
scwin.onpageunload = function() {};
scwin.makeDataList = function() {
    var dlOptions = {
        "id": "dl_dynamic",
        "type": "dataList",
        "option": {
            "baseNode": "list",
            "saveRemovedData": "true",
            "repeatNode": "map"
        },
        "columnInfo": [{
            "id": "codeNm",
            "name": "name1",
            "dataType": "text"
        }, {
            "id": "codeNo",
            "name": "name2",
            "dataType": "text"
        }, {
            "id": "upper",
            "name": "name3",
            "dataType": "text"
        }]
    };
    create(dlOptions);
};
scwin.__checkErrLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand('assert', 'scwin.__checkErrLog() == ""', 'true');
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
